function toBinary(s){ var o=[]; for(var i=0;i<s.length;i++) o.push(s.charCodeAt(i).toString(2).padStart(8,'0')); return o.join(' '); }
function toHex(s){ var o=[]; for(var i=0;i<s.length;i++) o.push(s.charCodeAt(i).toString(16).padStart(2,'0')); return o.join(' '); }
function fromBinary(b){ var parts=String(b||'').trim().split(/\s+/); var o=''; for(var i=0;i<parts.length;i++){ if(/^[01]{1,8}$/.test(parts[i])) o+=String.fromCharCode(parseInt(parts[i],2)); } return o; }
function fromHex(h){ var parts=String(h||'').trim().split(/\s+/); var o=''; for(var i=0;i<parts.length;i++){ if(/^[0-9a-fA-F]{1,2}$/.test(parts[i])) o+=String.fromCharCode(parseInt(parts[i],16)); } return o; }

var EXPORTS={toBinary:toBinary,toHex:toHex,fromBinary:fromBinary,fromHex:fromHex};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BinaryForgePure = EXPORTS; }
